#include <bits/stdc++.h>
using namespace std;

struct Node {
    char ch;
    int w;
    Node *l, *r;
    Node(char c, int w) : ch(c), w(w), l(nullptr), r(nullptr) {}
};

struct cmp {
    bool operator()(Node* a, Node* b) {
        if (a->w != b->w) return a->w > b->w;
        return a->ch > b->ch;
    }
};

void dfs(Node* root, string code, map<char,string>& res) {
    if (!root) return;
    if (!root->l && !root->r) {
        res[root->ch] = code;
        return;
    }
    dfs(root->l, code + "0", res);
    dfs(root->r, code + "1", res);
}

int main() {
    int n; cin >> n;
    vector<char> order(n);
    map<char,int> freq;
    priority_queue<Node*, vector<Node*>, cmp> pq;
    for (int i = 0; i < n; i++) {
        char c; int f;
        cin >> c >> f;
        order[i] = c;
        freq[c] = f;
        pq.push(new Node(c, f));
    }
    while (pq.size() > 1) {
        Node* a = pq.top(); pq.pop();
        Node* b = pq.top(); pq.pop();
        Node* p = new Node(min(a->ch, b->ch), a->w + b->w);
        p->l = a; p->r = b;
        pq.push(p);
    }
    map<char,string> res;
    dfs(pq.top(), "", res);
    for (char c : order) cout << c << ": " << res[c] << '\n';
    return 0;
}
```

```cpp
#include <bits/stdc++.h>
using namespace std;

int main() {
    int n; cin >> n;
    priority_queue<long long, vector<long long>, greater<long long>> pq;
    for (int i = 0; i < n; i++) {
        int x; cin >> x;
        pq.push(x);
    }

    long long wpl = 0;
    while (pq.size() > 1) {
        long long a = pq.top(); pq.pop();
        long long b = pq.top(); pq.pop();
        long long sum = a + b;
        wpl += sum;
        pq.push(sum);
    }

    cout << wpl << '\n';
    return 0;
}
```

**原理说明**：WPL = 所有非叶子节点权值之和。每次合并两个节点产生一个新的非叶子节点，其权值为两子之和，加入WPL累加。最终WPL即为所有中间节点权值总和。注意结果用 long long 防溢出。
